class AgeException extends Exception {
    public AgeException(String msg) { super(msg); }
}
public class CustomExDemo {
    static void checkAge(int age) throws AgeException {
        if (age < 18) throw new AgeException("Access Denied");
    }
    public static void main(String[] args) {
        try {
            checkAge(15);
        } catch (AgeException e) {
            System.out.println("Caught: " + e.getMessage());
        }
    }
}

import java.io.*;
public class FileIOUtils {
    public static void main(String[] args) throws IOException {
        FileOutputStream fos = new FileOutputStream("lab.txt");
        fos.write(65); // Writes char 'A'
        fos.close();

        FileInputStream fis = new FileInputStream("lab.txt");
        int ch;
        while ((ch = fis.read()) != -1) {
            System.out.print((char)ch);
        }
        fis.close();
    }
}
